INSERT OR REPLACE INTO "IMPORT List Price" SELECT coalesce(k0."SKU", error('cells name a member SKU does not have: ' || c."SKU")), coalesce(k1."Country", error('cells name a member Country does not have: ' || c."Country")), coalesce(k2."Years", error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE)
FROM read_csv('cells/IMPORT List Price.csv', header = true, all_varchar = true) c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU" LEFT JOIN "dim Country" k1 ON k1.name = c."Country" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY ALL;
